import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { useCart } from '../context/CartContext';
import { useAuth } from '../context/AuthContext';
import styles from './Navbar.module.css';

const Navbar = () => {
  const { cartCount } = useCart();
  const { user, logout, isAdmin } = useAuth();
  const navigate = useNavigate();
  const [menuOpen, setMenuOpen] = useState(false);
  const [profileOpen, setProfileOpen] = useState(false);

  const handleLogout = () => {
    logout();
    setProfileOpen(false);
    navigate('/');
  };

  return (
    <nav className={styles.nav}>
      <div className={styles.top}>
        <div className="container" style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
          {/* Logo */}
          <Link to="/" className={styles.logo}>
            <span className={styles.logoIcon}>🌿</span>
            <div>
              <div className={styles.logoText}>Desi2Door</div>
              <div className={styles.logoTagline}>Farm Fresh Delivery</div>
            </div>
          </Link>

          {/* Actions */}
          <div className={styles.actions}>
            {user ? (
              <div className={styles.profileWrap}>
                <button className={styles.profileBtn} onClick={() => setProfileOpen(!profileOpen)}>
                  <span className={styles.profileAvatar}>{user.name.charAt(0).toUpperCase()}</span>
                  <span className={styles.profileName}>{user.name.split(' ')[0]}</span>
                  <span style={{ fontSize: 12 }}>▼</span>
                </button>
                {profileOpen && (
                  <>
                    <div className={styles.overlay} onClick={() => setProfileOpen(false)} />
                    <div className={styles.profileDropdown}>
                      <div className={styles.profileHeader}>
                        <div className={styles.profileAvatarLg}>{user.name.charAt(0).toUpperCase()}</div>
                        <div>
                          <div style={{ fontFamily: 'var(--font-display)', fontWeight: 700, fontSize: 16 }}>{user.name}</div>
                          <div style={{ fontSize: 13, color: 'var(--gray-400)' }}>📱 +91 {user.phone}</div>
                        </div>
                      </div>
                      <div className={styles.profileDivider} />
                      {isAdmin && (
                        <Link to="/admin" className={styles.dropItem} onClick={() => setProfileOpen(false)}>
                          <span>🏪</span> Admin Dashboard
                        </Link>
                      )}
                      <Link to="/orders" className={styles.dropItem} onClick={() => setProfileOpen(false)}>
                        <span>📦</span> My Orders
                      </Link>
                      <Link to="/wishlist" className={styles.dropItem} onClick={() => setProfileOpen(false)}>
                        <span>❤️</span> My Wishlist
                      </Link>
                      <Link to="/profile" className={styles.dropItem} onClick={() => setProfileOpen(false)}>
                        <span>✏️</span> Edit Profile
                      </Link>
                      <div className={styles.profileDivider} />
                      <button className={styles.logoutBtn} onClick={handleLogout}>
                        <span>🚪</span> Logout
                      </button>
                    </div>
                  </>
                )}
              </div>
            ) : (
              <Link to="/login" className={styles.loginBtn}>
                👤 Login / Sign Up
              </Link>
            )}

            <Link to="/cart" className={styles.cartBtn}>
              🛒 <span className={styles.cartText}>Cart</span>
              {cartCount > 0 && <span className={styles.badge}>{cartCount}</span>}
            </Link>

            <button className={styles.menuToggle} onClick={() => setMenuOpen(!menuOpen)}>
              {menuOpen ? '✕' : '☰'}
            </button>
          </div>
        </div>
      </div>

      {/* Category Nav */}
      <div className={`${styles.catNav} ${menuOpen ? styles.catNavOpen : ''}`}>
        <div className="container">
          <div className={styles.cats}>
            {[
              ['meat-fish', '🥩', 'Meat & Fish'],
              ['vegetables', '🥦', 'Vegetables'],
              ['dairy-eggs', '🥛', 'Dairy & Eggs'],
              ['oils-ghee', '🫙', 'Organic'],
              ['millets-groceries', '🌾', 'Millets'],
              ['dry-fruits', '🥜', 'Dry Fruits'],
              ['masalas', '🌶️', 'Masalas'],
              ['chocolates', '🍫', 'Chocolates'],
            ].map(([cat, emoji, label]) => (
              <Link key={cat} to={`/shop?category=${cat}`} className={styles.catItem} onClick={() => setMenuOpen(false)}>
                {emoji} {label}
              </Link>
            ))}
          </div>
        </div>
      </div>
    </nav>
  );
};

export default Navbar;
